<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {request,ApiError} from '../lib/api';
import {workStatuses,workUrgencies,workDateParts,workPlannedAt,sortWorkTasks,type WorkTask,type WorkStatus} from '../lib/work-tasks';
const props=defineProps<{foreground:boolean}>();
const emit=defineEmits<{(e:'auth-expired'):void}>();
const tasks=ref<WorkTask[]>([]),loading=ref(false),busy=ref(false),error=ref('');
const filter=ref('active'),formOpen=ref(false),editing=ref(''),title=ref(''),day=ref(''),clock=ref('09:00'),urgency=ref(2),status=ref<WorkStatus>('todo');
const now=ref(Date.now());let timer:ReturnType<typeof setInterval>|undefined,disposed=false,loadSeq=0;
const filters=[{id:'active',label:'没干完的'},{id:'all',label:'全部'},{id:'todo',label:'待开始'},{id:'doing',label:'进行中'},{id:'done',label:'已完成'}];
const visible=computed(()=>sortWorkTasks(tasks.value).filter(t=>filter.value==='all'||(filter.value==='active'?t.status!=='done':t.status===filter.value)));
const done=computed(()=>tasks.value.filter(t=>t.status==='done').length);
const doing=computed(()=>tasks.value.filter(t=>t.status==='doing').length);
const urgent=computed(()=>tasks.value.filter(t=>t.status!=='done'&&t.urgency===3).length);
const completedPercent=computed(()=>tasks.value.length?Math.round(done.value/tasks.value.length*100):0);
const today=()=>workDateParts(new Date().toISOString()).day;
function timeLabel(t:WorkTask){if(!t.planned_at)return '还没安排时间';const p=workDateParts(t.planned_at);return p.day+' '+p.time;}
function overdue(t:WorkTask){return t.status!=='done'&&!!t.planned_at&&Date.parse(t.planned_at)<now.value;}
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
async function load(){if(busy.value)return;const seq=++loadSeq;loading.value=true;error.value='';try{const data=await request<{tasks:WorkTask[]}>('/work-tasks');if(!disposed&&seq===loadSeq)tasks.value=data.tasks;}catch(e){if(seq===loadSeq)fail(e);}finally{if(!disposed&&seq===loadSeq)loading.value=false;}}
function edit(t?:WorkTask){if(busy.value)return;error.value='';editing.value=t?.id||'';title.value=t?.title||'';urgency.value=t?.urgency||2;status.value=t?.status||'todo';const p=t?.planned_at?workDateParts(t.planned_at):{day:'',time:'09:00'};day.value=p.day;clock.value=p.time;formOpen.value=true;}
function upsert(t:WorkTask){tasks.value=[t,...tasks.value.filter(x=>x.id!==t.id)];}
async function save(){if(busy.value)return;if(!title.value.trim()){error.value='先写下要干什么工作。';return;}busy.value=true;loadSeq++;loading.value=false;error.value='';try{
 const task=await request<WorkTask>('/work-tasks'+(editing.value?'/'+editing.value:''),'POST',{title:title.value.trim(),planned_at:workPlannedAt(day.value,clock.value),urgency:urgency.value,status:status.value});
 if(disposed)return;upsert(task);formOpen.value=false;editing.value='';title.value='';
 }catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
async function advance(t:WorkTask){if(busy.value)return;busy.value=true;loadSeq++;loading.value=false;error.value='';const next:WorkStatus=t.status==='todo'?'doing':t.status==='doing'?'done':'todo';try{const task=await request<WorkTask>('/work-tasks/'+t.id+'/status','POST',{status:next});if(!disposed)upsert(task);}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
function remove(t:WorkTask){if(busy.value)return;uni.showModal({title:'删除这项工作？',content:t.title,confirmText:'删除',confirmColor:'#a54e3e',success:async r=>{if(!r.confirm||disposed||busy.value)return;busy.value=true;loadSeq++;loading.value=false;error.value='';try{await request('/work-tasks/'+t.id+'/delete','POST',{});if(!disposed){tasks.value=tasks.value.filter(x=>x.id!==t.id);if(editing.value===t.id)formOpen.value=false;}}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}});}
watch(()=>props.foreground,value=>{if(value)load();});
onMounted(()=>{load();timer=setInterval(()=>{now.value=Date.now();},60000);});
onBeforeUnmount(()=>{disposed=true;loadSeq++;clearInterval(timer);});
</script>
<template>
<view class="work-zone">
 <view class="work-hero"><view><text class="eyebrow">WORK / 今日牛马工单</text><text class="work-title">牛马痛苦区</text><text class="subtitle">把活记下来，别让脑子替老板加班。</text></view><button class="add" @click="edit()" :disabled="busy">＋ 记一件破事</button></view>
 <view class="metrics"><view><text class="metric-value">{{tasks.length-done}}</text><text>还没干完</text></view><view><text class="metric-value">{{doing}}</text><text>正在硬扛</text></view><view><text class="metric-value urgent-number">{{urgent}}</text><text>紧急待办</text></view><view><text class="metric-value">{{done}}</text><text>已甩掉的锅</text></view></view>
 <view class="progress-label"><text>收工进度</text><text>{{done}} / {{tasks.length}} · {{completedPercent}}%</text></view><view class="progress-track"><view :style="{width:completedPercent+'%'}"/></view>
 <view v-if="formOpen" class="task-form"><text class="section-title">{{editing?'修改这项工作':'又来活了'}}</text><text class="field-label">什么工作</text><input v-model="title" :maxlength="120" placeholder="例如：周五前把项目方案写完" class="task-input"/>
 <text class="field-label">什么时候做 · 北京时间</text><view class="date-row"><picker mode="date" :value="day||today()" @change="day=$event.detail.value"><view class="picker-box">{{day||'选择日期（可不填）'}} ▾</view></picker><picker mode="time" :value="clock" @change="clock=$event.detail.value"><view class="picker-box">{{clock}} ▾</view></picker><button v-if="day" class="small-link" @click="day=''">暂不安排</button></view>
 <text class="field-label">紧急程度</text><view class="options"><button v-for="p in workUrgencies" :key="p.id" :class="['option',{chosen:urgency===p.id},'urgency-'+p.id]" @click="urgency=p.id">{{p.label}}</button></view>
 <text class="field-label">目前进度</text><view class="options"><button v-for="s in workStatuses" :key="s.id" :class="['option',{chosen:status===s.id}]" @click="status=s.id">{{s.label}}</button></view>
 <view class="form-actions"><button class="save" :disabled="busy||!title.trim()" @click="save">{{busy?'正在保存…':'保存工作'}}</button><button class="cancel" :disabled="busy" @click="formOpen=false">取消</button></view></view>
 <view class="toolbar"><view class="filters"><button v-for="f in filters" :key="f.id" :class="{selected:filter===f.id}" @click="filter=f.id">{{f.label}}</button></view><button class="small-link" :disabled="loading||busy" @click="load">{{loading?'读取中…':'刷新'}}</button></view>
 <text v-if="error" class="work-error" selectable>{{error}}</text>
 <text class="sort-hint">未完成优先，紧急的先看，再按计划时间排列。</text>
 <view v-if="!visible.length" class="empty"><text class="empty-symbol">☕</text><text>{{loading?'正在清点今天的痛苦…':filter==='done'?'还没划掉第一项，慢慢来。':'这里暂时没活，趁现在喘口气。'}}</text><button v-if="!loading&&!tasks.length" class="small-link" @click="edit()">记下第一项工作 →</button></view>
 <view v-for="t in visible" :key="t.id" :class="['task-card',{finished:t.status==='done'}]"><view class="task-top"><text :class="['badge','urgency-'+t.urgency]">{{workUrgencies[t.urgency-1].label}}</text><text class="status">{{workStatuses.find(s=>s.id===t.status)?.label}}</text></view><text class="task-name">{{t.title}}</text><view class="task-time"><text>◷ {{timeLabel(t)}}</text><text v-if="overdue(t)" class="overdue">已过计划时间</text></view><view class="task-actions"><button class="advance" :disabled="busy" @click="advance(t)">{{t.status==='todo'?'开始干活':t.status==='doing'?'✓ 搞定了':'重新打开'}}</button><button class="small-link" :disabled="busy" @click="edit(t)">编辑</button><button class="small-link delete" :disabled="busy" @click="remove(t)">删除</button></view></view>
</view>
</template>
<style scoped>
.work-zone{color:#5c574d;padding:6px 0 30px}.work-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;background:#ede5d5;border:1px solid #ded1bb;padding:30px;border-radius:20px}.eyebrow,.subtitle,.work-title{display:block}.eyebrow{font-size:10px;letter-spacing:2px;color:#948367}.work-title{font-size:32px;font-weight:800;margin:12px 0}.subtitle{font-size:13px;color:#918473;line-height:1.8}.add,.save{background:#74664e;color:#fff9ed;border:0;border-radius:10px;font-size:14px;padding:12px 20px;white-space:nowrap;margin:0;line-height:1.4}.metrics{display:grid;grid-template-columns:repeat(4,1fr);margin:22px 0;gap:10px}.metrics>view{background:#faf8f1;border:1px solid #e3ddcf;border-radius:12px;padding:18px;text-align:center;font-size:12px;color:#958877}.metric-value{display:block;font-size:27px;color:#70634f;font-weight:700;margin-bottom:8px}.metric-value.urgent-number{color:#ac6750}.progress-label{display:flex;justify-content:space-between;font-size:12px;color:#938571}.progress-track{height:7px;background:#e8e2d8;border-radius:10px;overflow:hidden;margin:10px 0 24px}.progress-track>view{height:100%;background:#a2ac78;transition:width .2s}.task-form{background:#fffdf7;border:1px solid #d9cdb9;border-radius:16px;padding:24px;margin-bottom:24px}.section-title{font-size:20px;font-weight:700}.field-label{display:block;font-size:12px;color:#897b65;margin:20px 0 10px}.task-input{border:1px solid #ded5c6;background:#faf8f1;border-radius:9px;padding:12px;font-size:14px;box-sizing:content-box}.date-row,.options,.form-actions,.task-actions,.task-top{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.picker-box{padding:12px;border:1px solid #ded5c6;border-radius:9px;font-size:13px;background:#faf8f1}.option,.cancel{padding:9px 17px;font-size:13px;line-height:1.4;background:#f1eee7;color:#8a806e;border-radius:8px;border:1px solid transparent;margin:0}.option.chosen{background:#e8e1cf;border-color:#ab9877;color:#62543e}.option.chosen.urgency-3{background:#f4e2d8;border-color:#c99578;color:#9c6146}.form-actions{margin-top:24px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px}.filters{display:flex;flex-wrap:wrap;gap:6px}.filters button{font-size:12px;background:transparent;color:#948773;padding:9px 12px;border-radius:8px;margin:0;line-height:1.4}.filters button.selected{background:#e9e0d0;color:#66563e}.small-link{font-size:12px;color:#91816b;background:none;border:0;padding:8px 4px;margin:0;line-height:1.5}.small-link::after,.filters button::after,.add::after,.save::after{border:0}.sort-hint{display:block;font-size:10px;color:#aa9f8d;margin:13px 0 18px}.task-card{padding:22px 24px;background:#fffdf7;border:1px solid #e2dbcd;border-radius:14px;margin:12px 0}.task-top{justify-content:space-between}.badge{font-size:11px;padding:5px 10px;border-radius:6px;background:#eee9dd;color:#918066}.badge.urgency-3{background:#f7e1d7;color:#a3664e}.badge.urgency-1{background:#e8ecdd;color:#839066}.status{font-size:11px;color:#9f927b}.task-name{display:block;font-size:17px;font-weight:600;margin:15px 0;line-height:1.65;overflow-wrap:anywhere;white-space:pre-wrap}.task-time{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:#9b8c75}.overdue{color:#ac6750}.task-actions{margin-top:18px}.advance{background:#e8edd9;color:#7c8957;font-size:12px;padding:8px 14px;border-radius:8px;margin:0;line-height:1.5}.delete{margin-left:auto;color:#b19888}.finished{background:#f7f5ee}.finished .task-name{text-decoration:line-through;color:#a79e8b}.empty{padding:45px;text-align:center;font-size:13px;color:#a0947e}.empty>text{display:block;line-height:2}.empty-symbol{font-size:32px;margin-bottom:12px}.work-error{display:block;padding:12px;color:#ad5944;background:#f8e9e2;border-radius:10px;margin:12px 0;font-size:13px}@media(max-width:760px){.work-hero{padding:22px 18px;align-items:flex-start;flex-direction:column}.work-title{font-size:29px}.metrics>view{padding:14px 5px;font-size:10px}.metric-value{font-size:23px}.task-form,.task-card{padding:18px}.toolbar{align-items:flex-start}.filters{gap:3px}.filters button{padding:8px}.date-row{gap:7px}.empty{padding:35px 12px}}
</style>
